INSERT INTO venues (id, owner_id, slug, name, neighborhood, event_category, base_price, capacity_range, description, latitude, longitude)
VALUES
    (1, 1, 'grand-pavilion', 'The Grand Pavilion', 'Thane / Kasarvadavali', 'Weddings', 320000.00, '500 guests', 'A majestic venue featuring premium lawn space and a grand stage setup for high-capacity celebrations.', 19.2558000, 72.9675000),
    (2, 2, 'harmony-hall', 'Harmony Concert Hall', 'Shivajinagar, Pune', 'Music Concerts', 500000.00, '1200 guests', 'A concert-focused auditorium in Shivajinagar built for live performances, cultural nights, and stage-forward events.', 18.5314000, 73.8446000),
    (3, 3, 'spice-garden', 'Spice Garden', 'Kothrud, Pune', 'Birthday Parties', 180000.00, '350 guests', 'An intimate open-air garden space that works beautifully for birthdays, mehendi functions, and relaxed evening events.', 18.5074000, 73.8077000),
    (4, 4, 'river-paradise-resort', 'River Paradise Resort', 'Kolavadi, Pune', 'Luxury Receptions', 320000.00, '450 guests', 'A polished resort venue in Kolavadi suited for receptions, family gatherings, and premium indoor celebrations.', 18.5174000, 73.8417000),
    (5, 5, 'le-meridien-resort', 'Le Meridien Resort', 'Panchgani / Mahabaleshwar', 'Luxury Receptions', 350000.00, '250 guests', 'A scenic hill retreat for destination weddings, intimate receptions, and relaxed weekend celebrations.', 17.9237000, 73.8134000),
    (6, 1, 'mahalaxmi-lawns', 'Mahalaxmi Lawns', 'Kharadi, Pune', 'Weddings', 750000.00, '2000 guests', 'Massive sprawling lawns in Kharadi built for grand weddings, large receptions, and premium social events.', 18.5511000, 73.9474000),
    (7, 2, 'conrad-pune', 'Conrad Pune', 'Mangaldas Road, Pune', 'Corporate Events', 900000.00, '800 guests', 'A luxury city landmark on Mangaldas Road with ballroom styling for elite corporate events, galas, and premium weddings.', 18.5367000, 73.8849000),
    (8, 3, 'jw-marriott-grand-ballroom', 'JW Marriott Grand Ballroom', 'Senapati Bapat Road, Pune', 'Luxury Receptions', 850000.00, '1000 guests', 'A flagship ballroom venue on Senapati Bapat Road for grand receptions, galas, and polished luxury celebrations.', 18.5293000, 73.8291000),
    (9, 4, 'blue-diamond', 'Blue Diamond', 'Koregaon Park, Pune', 'Luxury Receptions', 600000.00, '500 guests', 'An iconic Koregaon Park property combining heritage and modern luxury for premium weddings and social gatherings.', 18.5369000, 73.8975000),
    (10, 5, 'hyatt-regency', 'Hyatt Regency', 'Viman Nagar, Pune', 'Conferences', 500000.00, '700 guests', 'A sleek contemporary venue in Viman Nagar for conferences, exhibitions, and business events.', 18.5679000, 73.9143000),
    (11, 1, 'sunnys-world', 'Sunny''s World', 'Pashan, Pune', 'Weddings', 450000.00, '1500 guests', 'A hilltop resort venue with panoramic views and large-format lawns for destination weddings and celebrations.', 18.5420000, 73.7810000),
    (12, 2, 'oxford-golf-resort', 'Oxford Golf Resort', 'Bavdhan, Pune', 'Weddings', 550000.00, '600 guests', 'A serene valley resort in Bavdhan with green backdrops for weddings, retreats, and premium outdoor functions.', 18.5203000, 73.7803000),
    (13, 3, 'philippine-international-convention-center', 'Philippine International Convention Center', 'Senapati Bapat Rd, Pune', 'Exhibitions', 400000.00, '2000 guests', 'A convention-scale venue for trade fairs, exhibitions, and large corporate seminars.', 18.5300000, 73.8295000),
    (14, 4, 'the-cult-terra-house', 'The Cult - Terra | House', 'Magarpatta, Pune', 'Cocktail Nights', 250000.00, '400 guests', 'An outdoor garden lounge with an electric atmosphere for nightlife-led events, cocktails, and lively celebrations.', 18.5150000, 73.9250000),
    (15, 5, 'ballr-pune', 'Ballr Pune', 'Kalyani Nagar, Pune', 'Birthday Parties', 200000.00, '300 guests', 'A premium clubbing experience in Kalyani Nagar with sound and lighting for birthdays and DJ nights.', 18.5484000, 73.9046000),
    (16, 1, 'high-spirits-cafe', 'High Spirits Cafe', 'Koregaon Park, Pune', 'Music Concerts', 150000.00, '250 guests', 'A legendary Koregaon Park venue for intimate gigs, birthdays, and underground music nights.', 18.5362000, 73.8939000),
    (17, 2, 'skye-rooftop-by-eternia', 'SKYE Rooftop by Eternia', 'Yerawada, Pune', 'Cocktail Nights', 190000.00, '110-280 guests', 'A rooftop party space in Yerawada with sunset views and a lounge-first event layout.', 18.5524000, 73.8854000),
    (18, 3, 'eagle-turf-and-lawns', 'Eagle Turf and Lawns', 'Kondhwa Budruk, Pune', 'Product Launches', 155000.00, '100-320 guests', 'A launch-friendly turf and lawn venue in Kondhwa Budruk with display and media zones.', 18.5938000, 73.7240000),
    (19, 4, 'saffron-multi-purpose-hall', 'Saffron Multi-Purpose Hall', 'Wagholi, Pune', 'Exhibitions', 185000.00, '140-450 guests', 'A flexible multi-purpose hall in Wagholi suited to exhibitions, community events, and booth layouts.', 18.5750000, 73.9890000),
    (20, 5, 'the-corinthians-resort-pune', 'The Corinthians Resort Pune', 'Undri, Pune', 'Luxury Receptions', 245000.00, '220-900 guests', 'A premium resort property in Undri suited to weddings, receptions, and upscale social celebrations.', 18.5142000, 73.8799000)
