USE pune_event_hub;

ON DUPLICATE KEY UPDATE
    full_name = VALUES(full_name),
    email = VALUES(email),
    phone_number = VALUES(phone_number),
    role = VALUES(role),
    is_active = VALUES(is_active);

ON DUPLICATE KEY UPDATE
    owner_id = VALUES(owner_id),
    slug = VALUES(slug),
    name = VALUES(name),
    neighborhood = VALUES(neighborhood),
    event_category = VALUES(event_category),
    base_price = VALUES(base_price),
    capacity_range = VALUES(capacity_range),
    description = VALUES(description),
    latitude = VALUES(latitude),
    longitude = VALUES(longitude);

ON DUPLICATE KEY UPDATE
    venue_id = VALUES(venue_id),
    slot_start = VALUES(slot_start),
    slot_end = VALUES(slot_end),
    status = VALUES(status),
    hold_reference = VALUES(hold_reference),
    hold_expires_at = VALUES(hold_expires_at);

ON DUPLICATE KEY UPDATE
    venue_id = VALUES(venue_id),
    image_path = VALUES(image_path),
    sort_order = VALUES(sort_order);

ON DUPLICATE KEY UPDATE
    venue_id = VALUES(venue_id),
    user_id = VALUES(user_id),
    rating = VALUES(rating),
    review_text = VALUES(review_text),
    ai_sentiment_score = VALUES(ai_sentiment_score);

